#include "stdlib/blas/ext/base/cany.h"
#include "stdlib/complex/float32/ctor.h"
#include "stdlib/complex/float32/real.h"
#include "stdlib/complex/float32/imag.h"
#include "stdlib/math/base/assert/is_nanf.h"
#include "stdlib/blas/base/shared.h"
#include "stdlib/strided/base/stride2offset.h"
#include <stdbool.h>

/**
* Tests whether at least one element in a single-precision complex floating-point strided array is truthy.
*
* @param N        number of indexed elements
* @param X        input array
* @param strideX  stride length
* @return         boolean result
*/
bool API_SUFFIX(stdlib_strided_cany)( const CBLAS_INT N, const stdlib_complex64_t *X, const CBLAS_INT strideX ) {
	CBLAS_INT ox = stdlib_strided_stride2offset( N, strideX );
	return API_SUFFIX(stdlib_strided_cany_ndarray)( N, X, strideX, ox );
}

/**
* Tests whether at least one element in a single-precision complex floating-point strided array is truthy using alternative indexing semantics.
*
* @param N        number of indexed elements
* @param X        input array
* @param strideX  stride length
* @param offsetX  starting index
* @return         boolean result
*/
bool API_SUFFIX(stdlib_strided_cany_ndarray)( const CBLAS_INT N, const stdlib_complex64_t *X, const CBLAS_INT strideX, const CBLAS_INT offsetX ) {
	stdlib_complex64_t v;
	CBLAS_INT ix;
	CBLAS_INT i;
	float re;
	float im;

	if ( N <= 0 ) {
		return false;
	}
	ix = offsetX;
	for ( i = 0; i < N; i++ ) {
		v = X[ ix ];
		re = stdlib_complex64_real( v );
		im = stdlib_complex64_imag( v );
		if ( ( re != 0.0f && !stdlib_base_is_nanf( re ) ) || ( im != 0.0f && !stdlib_base_is_nanf( im ) ) ) {
			return true;
		}
		ix += strideX;
	}
	return false;
}
